import { readDatabase, updateDatabase, hasGithubConfig, publishSchedule } from './github-store.js';
import { login, logout, currentSession, changePassword, hashPassword, adminResetPassword } from './auth.js';
import { uid, clean, yes, num, dateKey, addDays, monthKey, escapeHtml, USER_DEFAULTS, SHIFT_DEFAULTS } from './schema.js';
import { generateSchedule, validateSchedule, validateConfiguration, scheduleHealth, employeeStats, fairnessReport, manualAssignmentWarnings, reconcilePto, swapEligibleCounterShifts } from './scheduler.js';

const $=id=>document.getElementById(id);
const State={db:null,session:null,page:'dashboard',month:new Date(new Date().getFullYear(),new Date().getMonth(),1),filters:{employees:[],shift:'',showUnfilled:true}};
const pageTitles={dashboard:'Dashboard',calendar:'Schedule Calendar',mine:'My Schedule',swaps:'Swap Market',requests:'PTO / Availability',weeklyavailability:'Weekly Availability',employees:'Pharmacist Management',admins:'Administrator Accounts',skills:'Employee Skills',shifts:'Shift Definitions',staffing:'Staffing Requirements',preceptors:'Preceptor Calendar',fairness:'Fairness Report',settings:'Settings',audit:'Audit Log'};

function esc(v){return escapeHtml(v)}
function attr(v){return esc(v).replace(/`/g,'&#96;')}
function toast(msg,type='ok'){const d=document.createElement('div');d.className=`alert ${type==='error'?'alert-danger':type==='warn'?'alert-warn':'alert-ok'}`;d.style.position='fixed';d.style.right='18px';d.style.bottom='18px';d.style.zIndex='100';d.style.maxWidth='430px';d.textContent=msg;document.body.appendChild(d);setTimeout(()=>d.remove(),4200);}
function fmt(v){if(!v)return'';try{return new Date(v).toLocaleString();}catch{return String(v)}}
function boolBadge(v){return yes(v)?'<span class="badge badge-ok">Yes</span>':'<span class="badge">No</span>'}
function roleGuard(){if(!State.session?.isAdmin)throw new Error('Administrator access required.');}
function audit(db,action,details={},override=false,overrideReason=''){db.audit.push({id:uid('AUD'),timestamp:new Date().toISOString(),user:State.session?.username||'SYSTEM',action,date:details.date||'',pharmacist:details.pharmacist||'',oldShift:details.oldShift||'',newShift:details.newShift||'',oldValue:details.oldValue||'',newValue:details.newValue||'',override,overrideReason,details:details.details||''});}
async function save(mutator,message){const r=await updateDatabase(async db=>{const x=await mutator(db);return x;},message);State.db=r.db;return r.result;}
async function reload(){const x=await readDatabase();State.db=x.db;renderPage(State.page);}

async function boot(){
  $('loginForm').addEventListener('submit',handleLogin);$('logoutBtn').onclick=()=>{logout();location.reload()};$('refreshBtn').onclick=()=>reload().catch(e=>toast(e.message,'error'));$('changePasswordBtn').onclick=openChangePassword;
  document.querySelectorAll('#nav button[data-page]').forEach(b=>b.onclick=()=>renderPage(b.dataset.page));
  const s=currentSession();if(s&&hasGithubConfig()){State.session=s;try{await loadApp();}catch(e){$('loginError').textContent=e.message;}}
  else if(!hasGithubConfig()){ $('loginError').textContent='This browser needs a one-time secure connection to the private NeoChrono database.'; const b=$('setupDeviceBtn'); if(b)b.classList.remove('hidden'); }
}
async function handleLogin(e){e.preventDefault();$('loginError').textContent='';const sb=$('setupDeviceBtn');if(sb)sb.classList.add('hidden');$('loginButton').disabled=true;try{State.session=await login($('loginUsername').value,$('loginPassword').value);await loadApp();if(State.session.mustChangePassword)openChangePassword();}catch(err){$('loginError').textContent=err.message;if(/not connected|token|GitHub/i.test(String(err.message||''))&&sb)sb.classList.remove('hidden');}finally{$('loginButton').disabled=false;}}
async function loadApp(){const {db}=await readDatabase();State.db=db;$('loginView').classList.add('hidden');$('app').classList.remove('hidden');$('sessionName').textContent=State.session.name;$('sessionRole').textContent=State.session.isAdmin?'Administrator':'Pharmacist';document.querySelectorAll('.admin-only').forEach(x=>x.classList.toggle('hidden',!State.session.isAdmin));renderPage('dashboard');}
function renderPage(page){if(!State.db)return;const adminOnly=['employees','admins','skills','shifts','staffing','preceptors','fairness','settings','audit'];if(adminOnly.includes(page)&&!State.session.isAdmin)page='dashboard';State.page=page;$('pageTitle').textContent=pageTitles[page]||'NeoChrono';document.querySelectorAll('#nav button[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const f={dashboard:renderDashboard,calendar:renderCalendar,mine:renderMine,swaps:renderSwaps,requests:renderRequests,weeklyavailability:renderWeeklyAvailability,employees:renderEmployees,admins:renderAdmins,skills:renderSkills,shifts:renderShifts,staffing:renderStaffing,preceptors:renderPreceptors,fairness:renderFairness,settings:renderSettings,audit:renderAudit}[page];$('content').innerHTML='';try{f();}catch(e){$('content').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`;}}

function renderDashboard(){const h=scheduleHealth(State.db),stats=employeeStats(State.db),pending=State.db.requests.filter(r=>clean(r.status).toLowerCase()==='pending').length;const latest=[...State.db.schedulePeriods].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))[0];$('content').innerHTML=`<div class="section-title"><div><h3>Schedule Health</h3><p>Coverage, requests, and workload at a glance.</p></div><div class="top-actions">${State.session.isAdmin?'<button class="btn btn-primary" id="generateBtn">Generate Schedule</button><button class="btn btn-secondary" id="configBtn">Config Check</button><button class="btn btn-secondary" id="validateBtn">Validate Schedule</button><button class="btn btn-ghost" id="exportBtn">Export CSV</button><button class="btn btn-success" id="finalizeBtn">Finalize / Publish</button>':''}</div></div><div class="cards"><div class="card kpi"><strong>${h.required}</strong><span>Required slots</span></div><div class="card kpi"><strong>${h.filled}</strong><span>Filled</span></div><div class="card kpi"><strong>${h.unfilled}</strong><span>Unfilled</span></div><div class="card kpi"><strong>${h.coveragePercent}%</strong><span>Coverage</span></div></div><div class="grid-2 mt12"><div class="card"><h3>Current period</h3>${latest?`<p><b>${esc(latest.startDate)}</b> through <b>${esc(latest.endDate)}</b></p><p>Status: <span class="badge ${latest.status==='FINALIZED'?'badge-ok':''}">${esc(latest.status)}</span></p>`:'<p class="muted">No generated schedule period yet.</p>'}</div><div class="card"><h3>Requests</h3><p><b>${pending}</b> pending request(s)</p><p><b>${State.db.swaps.filter(s=>clean(s.status)==='OPEN').length}</b> open swap posting(s)</p></div></div><div class="card mt12"><h3>Employee hours</h3><div class="table-wrap"><table class="table"><thead><tr><th>Pharmacist</th><th>Total hours</th><th>Shifts</th><th>Weekend shifts</th><th>Schedule Type</th></tr></thead><tbody>${stats.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.totalHours}</td><td>${x.shifts}</td><td>${x.weekendShifts}</td><td>${esc(x.scheduleType||'')}</td></tr>`).join('')}</tbody></table></div></div>`;
  if(State.session.isAdmin){$('generateBtn').onclick=openGenerate;$('configBtn').onclick=()=>openConfigValidation();$('validateBtn').onclick=()=>openValidation();$('exportBtn').onclick=exportCsv;$('finalizeBtn').onclick=finalizeLatest;}
}

function openConfigValidation(){const v=validateConfiguration(State.db);openModal('Configuration Validation',`<div class="cards"><div class="card kpi"><strong>${v.errors.length}</strong><span>Errors</span></div><div class="card kpi"><strong>${v.warnings.length}</strong><span>Warnings</span></div></div>${v.errors.length?`<div class="alert alert-danger mt12"><b>Errors</b><br>${v.errors.map(esc).join('<br>')}</div>`:'<div class="alert alert-ok mt12">No blocking configuration errors.</div>'}${v.warnings.length?`<div class="alert alert-warn"><b>Warnings</b><br>${v.warnings.map(esc).join('<br>')}</div>`:''}`,[{text:'Close',cls:'btn-secondary',fn:closeModal}]);}
function openGenerate(){const next=new Date();next.setDate(next.getDate()+1);openModal('Generate Schedule',`<div class="alert alert-warn">Generation preserves locked assignments inside the selected period and regenerates the other required slots.</div><div class="form-grid"><div class="field"><label>Start date</label><input id="genStart" class="control" type="date" value="${dateKey(next)}"></div><div class="field"><label>Schedule days</label><input id="genDays" class="control" type="number" value="${num(State.db.settings.scheduleDays,60)}" min="1" max="75"></div></div>`,[{text:'Cancel',cls:'btn-secondary',fn:closeModal},{text:'Generate',cls:'btn-primary',fn:async()=>{try{const start=$('genStart').value,days=num($('genDays').value,60);const out=generateSchedule(State.db,start,{days,actor:State.session.username});await save(db=>{db.schedule=out.nextSchedule;db.schedulePeriods=out.periods;audit(db,'SCHEDULE_GENERATED',{date:start,newValue:out.generationId,details:`Generated ${out.startDate} to ${out.endDate}. Errors ${out.validation.errorCount}, warnings ${out.validation.warningCount}.`});},`Generate schedule ${out.generationId}`);closeModal();toast('Schedule generated.');renderPage('calendar');}catch(e){toast(e.message,'error');}}}]);}
function openValidation(){const latest=[...State.db.schedulePeriods].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))[0];const v=validateSchedule(State.db,latest?.generationId||'');openModal('Schedule Validation',`<div class="cards"><div class="card kpi"><strong>${v.errorCount}</strong><span>Errors</span></div><div class="card kpi"><strong>${v.warningCount}</strong><span>Warnings</span></div></div><div class="table-wrap mt12"><table class="table"><thead><tr><th>Severity</th><th>Date</th><th>Pharmacist</th><th>Issue</th><th>Message</th></tr></thead><tbody>${v.warnings.slice(0,500).map(w=>`<tr><td><span class="badge ${w.severity==='ERROR'?'badge-danger':'badge-warn'}">${esc(w.severity)}</span></td><td>${esc(w.date||'')}</td><td>${esc(w.pharmacist||'')}</td><td>${esc(w.type)}</td><td>${esc(w.message)}</td></tr>`).join('')}</tbody></table></div>`,[{text:'Close',cls:'btn-secondary',fn:closeModal}]);}
async function finalizeLatest(){roleGuard();const latest=[...State.db.schedulePeriods].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))[0];if(!latest){toast('No schedule period to finalize.','error');return;}const v=validateSchedule(State.db,latest.generationId);if(v.errorCount&&!confirm(`There are ${v.errorCount} validation error(s). Finalize anyway?`))return;const rows=State.db.schedule.filter(r=>r.generationId===latest.generationId);try{await publishSchedule(rows,{generationId:latest.generationId,startDate:latest.startDate,endDate:latest.endDate,publishedBy:State.session.username});await save(db=>{const p=db.schedulePeriods.find(x=>x.generationId===latest.generationId);if(p){p.status='FINALIZED';p.finalizedBy=State.session.username;p.finalizedAt=new Date().toISOString();}db.schedule.filter(r=>r.generationId===latest.generationId).forEach(r=>r.finalizedAt=new Date().toISOString());db.publishedSchedule=rows;audit(db,'SCHEDULE_FINALIZED',{newValue:latest.generationId,details:`Finalized and published ${latest.startDate} to ${latest.endDate}.`});},`Finalize ${latest.generationId}`);toast('Schedule finalized and published.');renderPage('dashboard');}catch(e){toast(e.message,'error');}}
function exportCsv(){const rows=State.db.schedule;if(!rows.length){toast('No schedule data.','warn');return;}const headers=['Date','Day','Shift','Slot','Assigned Pharmacist','Username','Hours','Credited Hours','Required Skill','Weekend','Weekend Group','Locked','Manual','Status','Warning'];const keys=['date','day','shift','slot','assignedPharmacist','username','hours','creditedHours','requiredSkill','weekend','weekendGroup','locked','manual','status','warning'];const q=v=>`"${String(v??'').replace(/"/g,'""')}"`;const csv=[headers.map(q).join(','),...rows.map(r=>keys.map(k=>q(r[k])).join(','))].join('\n');const blob=new Blob([csv],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`NeoChrono_Schedule_${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);}

function renderCalendar(mineOnly=false){if(!State.session.isAdmin&&!yes(State.db.settings.showFullScheduleToPharmacists))mineOnly=true;const y=State.month.getFullYear(),m=State.month.getMonth(),first=new Date(y,m,1),last=new Date(y,m+1,0),users=State.db.users.filter(u=>u.active!==false);let rows=State.db.schedule.filter(r=>{const d=new Date(`${r.date}T12:00:00`);return d.getFullYear()===y&&d.getMonth()===m;});if(mineOnly)rows=rows.filter(r=>r.username===State.session.username);if(State.filters.employees.length)rows=rows.filter(r=>State.filters.employees.includes(r.username));if(State.filters.shift)rows=rows.filter(r=>r.shift===State.filters.shift);if(!State.filters.showUnfilled)rows=rows.filter(r=>clean(r.status)!=='UNFILLED');const startPad=first.getDay(),cells=[];for(let i=0;i<startPad;i++)cells.push('<div></div>');for(let day=1;day<=last.getDate();day++){const d=new Date(y,m,day),dk=dateKey(d),dr=rows.filter(r=>r.date===dk).sort((a,b)=>a.shift.localeCompare(b.shift)||a.slot-b.slot);cells.push(`<div class="day-card ${[0,6].includes(d.getDay())?'weekend':''}"><div class="day-date">${day}</div>${dr.map(r=>`<div class="assignment ${clean(r.status)==='UNFILLED'?'unfilled':''} ${yes(r.locked)?'locked':''}" data-assignment="${attr(r.assignmentId)}"><div class="shift">${esc(r.shift)} ${r.slot>1?'#'+r.slot:''}</div><div class="person">${esc(r.assignedPharmacist||'UNFILLED')}</div>${r.warning?`<div class="danger-text small">${esc(r.warning)}</div>`:''}</div>`).join('')}</div>`);}const multi=mineOnly?'':`<div class="field"><label>Pharmacists (up to 6)</label><select id="calEmployees" class="control" multiple size="4">${users.map(u=>`<option value="${attr(u.username)}" ${State.filters.employees.includes(u.username)?'selected':''}>${esc(u.pharmacistName||u.name)}</option>`).join('')}</select></div><div class="field"><label>Shift</label><select id="calShift" class="control"><option value="">All</option>${State.db.shifts.filter(s=>s.active!==false).map(s=>`<option ${State.filters.shift===s.shift?'selected':''}>${esc(s.shift)}</option>`).join('')}</select></div><label class="field"><span>Show Unfilled</span><input id="showUnfilled" type="checkbox" ${State.filters.showUnfilled?'checked':''}></label>`;$('content').innerHTML=`<div class="section-title"><div><h3>${mineOnly?'My Schedule':'Schedule Calendar'}</h3><p>${first.toLocaleString(undefined,{month:'long',year:'numeric'})}</p></div></div><div class="toolbar"><button class="btn btn-secondary" id="prevMonth">← Previous</button><button class="btn btn-secondary" id="todayMonth">Today</button><button class="btn btn-secondary" id="nextMonth">Next →</button>${multi}</div><div class="legend"><span>Click an assignment to view details${State.session.isAdmin?' or manually edit it':''}.</span></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="calendar-head">${x}</div>`).join('')}${cells.join('')}</div>`;$('prevMonth').onclick=()=>{State.month=new Date(y,m-1,1);renderCalendar(mineOnly)};$('nextMonth').onclick=()=>{State.month=new Date(y,m+1,1);renderCalendar(mineOnly)};$('todayMonth').onclick=()=>{const n=new Date();State.month=new Date(n.getFullYear(),n.getMonth(),1);renderCalendar(mineOnly)};if(!mineOnly){$('calEmployees').onchange=e=>{State.filters.employees=[...e.target.selectedOptions].slice(0,6).map(o=>o.value);renderCalendar(false)};$('calShift').onchange=e=>{State.filters.shift=e.target.value;renderCalendar(false)};$('showUnfilled').onchange=e=>{State.filters.showUnfilled=e.target.checked;renderCalendar(false)}}document.querySelectorAll('[data-assignment]').forEach(x=>x.onclick=()=>openAssignment(x.dataset.assignment));}
function renderMine(){renderCalendar(true)}
async function openAssignment(id){const r=State.db.schedule.find(x=>x.assignmentId===id);if(!r)return;const userOptions=State.db.users.filter(u=>u.active!==false).map(u=>`<option value="${attr(u.username)}" ${u.username===r.username?'selected':''}>${esc(u.pharmacistName||u.name)}</option>`).join('');const body=`<div class="grid-2"><div class="card"><b>${esc(r.date)} — ${esc(r.shift)}</b><p>Slot ${r.slot}</p><p>Status: ${esc(r.status)}</p><p>Required skill: ${esc(r.requiredSkill)}</p><p>Hours: ${r.creditedHours}</p></div><div class="card"><p><b>Assigned:</b> ${esc(r.assignedPharmacist||'UNFILLED')}</p><p><b>Locked:</b> ${yes(r.locked)?'Yes':'No'}</p><p><b>Manual:</b> ${yes(r.manual)?'Yes':'No'}</p><p>${esc(r.warning||'')}</p></div></div>${State.session.isAdmin?`<div class="field mt12"><label>Manual assignment</label><select id="manualUser" class="control"><option value="">UNFILLED</option>${userOptions}</select></div><div class="field mt12"><label>Override reason (required if rules are overridden)</label><textarea id="overrideReason" class="control"></textarea></div>`:''}`;const actions=[{text:'Close',cls:'btn-secondary',fn:closeModal}];if(State.session.isAdmin){actions.unshift({text:yes(r.locked)?'Unlock':'Lock',cls:'btn-ghost',fn:()=>toggleLock(id)});actions.unshift({text:'Save Assignment',cls:'btn-primary',fn:()=>saveManualAssignment(id)});actions.unshift({text:'Remove',cls:'btn-danger',fn:()=>removeAssignment(id)});}openModal('Assignment Details',body,actions);}
async function toggleLock(id){await save(db=>{const r=db.schedule.find(x=>x.assignmentId===id);r.locked=!yes(r.locked);r.updatedAt=new Date().toISOString();r.updatedBy=State.session.username;audit(db,r.locked?'ASSIGNMENT_LOCKED':'ASSIGNMENT_UNLOCKED',{date:r.date,pharmacist:r.assignedPharmacist,newShift:r.shift});},`Toggle lock ${id}`);closeModal();toast('Assignment updated.');renderPage('calendar');}
async function removeAssignment(id){if(!confirm('Remove this assignment and leave the required slot UNFILLED?'))return;await save(db=>{const r=db.schedule.find(x=>x.assignmentId===id);const old=r.assignedPharmacist;r.assignedPharmacist='UNFILLED';r.username='';r.status='UNFILLED';r.manual=true;r.warning='Manual unassignment';r.updatedAt=new Date().toISOString();r.updatedBy=State.session.username;audit(db,'ASSIGNMENT_REMOVED',{date:r.date,pharmacist:old,oldShift:r.shift,details:id});},`Remove assignment ${id}`);closeModal();toast('Assignment removed.');renderPage('calendar');}
async function saveManualAssignment(id){const username=$('manualUser').value;if(!username){return removeAssignment(id)}const w=manualAssignmentWarnings(State.db,id,username);let override=false,reason=clean($('overrideReason').value);if(!w.ok){const txt=`Rule warnings:\n${w.reasons.join('\n')}\n\nWeekly: ${w.weeklyBefore} → ${w.weeklyAfter}\nMonthly: ${w.monthlyBefore} → ${w.monthlyAfter}\nPeriod: ${w.periodBefore} → ${w.periodAfter}`;if(!State.db.settings.allowAdminRuleOverride){alert(txt);return;}if(!reason){alert(`${txt}\n\nEnter an override reason to continue.`);return;}if(!confirm(`${txt}\n\nOverride these rules?`))return;override=true;}await save(db=>{const r=db.schedule.find(x=>x.assignmentId===id),u=db.users.find(x=>x.username===username),old=r.assignedPharmacist;r.assignedPharmacist=u.pharmacistName||u.name;r.username=u.username;r.status='MANUAL';r.manual=true;r.warning=w.ok?'':w.reasons.join('; ');r.updatedAt=new Date().toISOString();r.updatedBy=State.session.username;audit(db,'ASSIGNMENT_CHANGED',{date:r.date,pharmacist:r.assignedPharmacist,oldShift:r.shift,newShift:r.shift,oldValue:old,newValue:r.assignedPharmacist,details:`Weekly ${w.weeklyAfter}; Monthly ${w.monthlyAfter}; Period ${w.periodAfter}`},override,reason);},`Manual assignment ${id}`);closeModal();toast('Assignment saved.');renderPage('calendar');}

function renderEmployees(){roleGuard();const rows=State.db.users;$('content').innerHTML=`<div class="section-title"><div><h3>Pharmacists</h3><p>Edit scheduling rules, preferred units, skills coverage, weekend rotation, resident/preceptor status, and credentials.</p></div><button class="btn btn-primary" id="addEmployee">+ Add Pharmacist</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Username</th><th>Active</th><th>Schedule</th><th>Weekend</th><th>Hours</th><th>Preceptor</th><th>Resident</th><th>Preferred</th><th>Off-Day Coverage</th><th></th></tr></thead><tbody>${rows.map(u=>`<tr><td><b>${esc(u.pharmacistName||u.name)}</b></td><td>${esc(u.username)}</td><td>${boolBadge(u.active)}</td><td>${esc(u.scheduleType)}</td><td>${esc(u.weekendGroup||'')}</td><td>${num(u.targetWeeklyHours,40)} / ${num(u.weeklyHourMaximum,40)}</td><td>${boolBadge(u.preceptor)}</td><td>${boolBadge(u.resident)}</td><td>${esc(u.preferredShiftType||'')}</td><td>${esc((u.offDayCoverageSkills||[]).join(', '))}</td><td><button class="btn btn-secondary btn-sm" data-edit-user="${attr(u.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div>`;$('addEmployee').onclick=()=>openEmployee(null);document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>openEmployee(b.dataset.editUser));}
function openEmployee(id){const u=id?State.db.users.find(x=>x.id===id):{...USER_DEFAULTS};const v=(k,d='')=>u?.[k]??d;const yn=(k)=>`<select id="emp_${k}" class="control"><option value="true" ${yes(v(k))?'selected':''}>Yes</option><option value="false" ${!yes(v(k))?'selected':''}>No</option></select>`;openModal(id?'Edit Pharmacist':'Add Pharmacist',`<div class="form-grid"><div class="field"><label>Name</label><input id="emp_name" class="control" value="${attr(v('pharmacistName')||v('name'))}"></div><div class="field"><label>Username</label><input id="emp_username" class="control" value="${attr(v('username'))}"></div><div class="field"><label>${id?'New password (leave blank to keep)':'Password'}</label><input id="emp_password" type="password" class="control"></div><div class="field"><label>Active</label>${yn('active')}</div><div class="field"><label>Schedule Type</label><select id="emp_scheduleType" class="control"><option ${v('scheduleType')==='Regular'?'selected':''}>Regular</option><option ${v('scheduleType')==='PRN'?'selected':''}>PRN</option><option value="7ON7OFF" ${v('scheduleType')==='7ON7OFF'?'selected':''}>7ON7OFF</option></select></div><div class="field"><label>Weekend Group</label><select id="emp_weekendGroup" class="control"><option></option>${['A','B','C'].map(x=>`<option ${v('weekendGroup')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Weekend Rotation Anchor Date</label><input id="emp_weekendRotationAnchorDate" type="date" class="control" value="${attr(v('weekendRotationAnchorDate'))}"></div><div class="field"><label>7-on/7-off Anchor Date</label><input id="emp_rotationAnchorDate" type="date" class="control" value="${attr(v('rotationAnchorDate'))}"></div><div class="field"><label>Weekly Hour Maximum</label><input id="emp_weeklyHourMaximum" type="number" class="control" value="${attr(v('weeklyHourMaximum',40))}"></div><div class="field"><label>Target Weekly Hours</label><input id="emp_targetWeeklyHours" type="number" class="control" value="${attr(v('targetWeeklyHours',40))}"></div><div class="field"><label>Maximum Evening Shifts / Month</label><input id="emp_maximumEveningShiftsPerMonth" type="number" class="control" value="${attr(v('maximumEveningShiftsPerMonth',7))}"></div><div class="field"><label>Preferred Shift Type / Home Unit</label><input id="emp_preferredShiftType" class="control" value="${attr(v('preferredShiftType'))}"></div><div class="field"><label>Off-Day Coverage Skills</label><input id="emp_offDayCoverageSkills" class="control" value="${attr((v('offDayCoverageSkills',[])||[]).join(', '))}"></div><div class="field"><label>Preceptor</label>${yn('preceptor')}</div><div class="field"><label>Resident</label>${yn('resident')}</div><div class="field"><label>Weekend Eligible</label>${yn('weekendEligible')}</div><div class="field"><label>Evening Eligible</label>${yn('eveningEligible')}</div><div class="field"><label>Night Eligible</label>${yn('nightEligible')}</div><div class="field"><label>Resident Covers Regular</label>${yn('residentCoversRegular')}</div><div class="field"><label>Resident Weekends</label>${yn('residentWeekends')}</div><div class="field"><label>Resident Evenings</label>${yn('residentEvenings')}</div><div class="field"><label>Resident Nights</label>${yn('residentNights')}</div><div class="field"><label>Preferred Start</label><input id="emp_preferredStartTime" type="time" class="control" value="${attr(v('preferredStartTime'))}"></div><div class="field"><label>Preferred End</label><input id="emp_preferredEndTime" type="time" class="control" value="${attr(v('preferredEndTime'))}"></div><div class="field"><label>Custom Hours Enabled</label>${yn('customHoursEnabled')}</div><div class="field"><label>Custom Hours Mode</label><select id="emp_customHoursMode" class="control"><option ${v('customHoursMode')==='SOFT'?'selected':''}>SOFT</option><option ${v('customHoursMode')==='HARD'?'selected':''}>HARD</option></select></div><div class="field"><label>SevenOn Weekly Handling</label><select id="emp_sevenOnWeeklyHandling" class="control"><option ${v('sevenOnWeeklyHandling')==='ENFORCE_MAX'?'selected':''}>ENFORCE_MAX</option><option ${v('sevenOnWeeklyHandling')==='AVERAGE_14_DAYS'?'selected':''}>AVERAGE_14_DAYS</option></select></div><div class="field"><label>Notes</label><textarea id="emp_notes" class="control">${esc(v('notes'))}</textarea></div></div>`,[{text:'Cancel',cls:'btn-secondary',fn:closeModal},...(id?[{text:'Delete',cls:'btn-danger',fn:()=>deleteEmployee(id)}]:[]),{text:'Save',cls:'btn-primary',fn:()=>saveEmployee(id)}]);}
async function saveEmployee(id){const get=k=>$(`emp_${k}`).value;const username=clean(get('username')),name=clean(get('name')),password=get('password');if(!username||!name){toast('Name and username are required.','error');return;}if(!id&&password.length<8){toast('Password must be at least 8 characters.','error');return;}let h=null;if(password)h=await hashPassword(password);await save(db=>{if(db.users.some(x=>x.id!==id&&clean(x.username).toLowerCase()===username.toLowerCase()))throw new Error('Username already exists.');let u=id?db.users.find(x=>x.id===id):{id:uid('EMP'),role:'Pharmacist'};Object.assign(u,{pharmacistName:name,name,username,active:get('active')==='true',scheduleType:get('scheduleType'),weekendGroup:get('weekendGroup'),weekendRotationAnchorDate:get('weekendRotationAnchorDate'),rotationAnchorDate:get('rotationAnchorDate'),weeklyHourMaximum:num(get('weeklyHourMaximum'),40),targetWeeklyHours:num(get('targetWeeklyHours'),40),maximumEveningShiftsPerMonth:num(get('maximumEveningShiftsPerMonth'),7),preferredShiftType:get('preferredShiftType'),offDayCoverageSkills:get('offDayCoverageSkills').split(/[,;|]/).map(x=>clean(x).toUpperCase()).filter(Boolean),preceptor:get('preceptor')==='true',resident:get('resident')==='true',weekendEligible:get('weekendEligible')==='true',eveningEligible:get('eveningEligible')==='true',nightEligible:get('nightEligible')==='true',residentCoversRegular:get('residentCoversRegular')==='true',residentWeekends:get('residentWeekends')==='true',residentEvenings:get('residentEvenings')==='true',residentNights:get('residentNights')==='true',preferredStartTime:get('preferredStartTime'),preferredEndTime:get('preferredEndTime'),customHoursEnabled:get('customHoursEnabled')==='true',customHoursMode:get('customHoursMode'),sevenOnWeeklyHandling:get('sevenOnWeeklyHandling'),notes:get('notes'),updatedAt:new Date().toISOString(),updatedBy:State.session.username});if(h)Object.assign(u,{passwordHash:h.hash,passwordSalt:h.salt,passwordIterations:h.iterations,mustChangePassword:false});if(!id)db.users.push(u);audit(db,id?'EMPLOYEE_UPDATED':'EMPLOYEE_CREATED',{pharmacist:name,newValue:username});},`${id?'Update':'Create'} pharmacist ${username}`);closeModal();toast('Pharmacist saved.');renderEmployees();}
async function deleteEmployee(id){if(!confirm('Delete this pharmacist record? Historical schedule rows will remain.'))return;await save(db=>{const u=db.users.find(x=>x.id===id);db.users=db.users.filter(x=>x.id!==id);db.skills=db.skills.filter(x=>x.username!==u?.username);audit(db,'EMPLOYEE_DELETED',{pharmacist:u?.pharmacistName||'',oldValue:u?.username||''});},`Delete pharmacist ${id}`);closeModal();renderEmployees();}

function renderAdmins(){roleGuard();$('content').innerHTML=`<div class="section-title"><div><h3>Administrator Accounts</h3><p>Only administrators can generate or manually modify the official schedule.</p></div><button class="btn btn-primary" id="addAdmin">+ Add Admin</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Username</th><th>Active</th><th>Last Login</th><th></th></tr></thead><tbody>${State.db.admins.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.username)}</td><td>${boolBadge(a.active)}</td><td>${esc(fmt(a.lastLogin))}</td><td><button class="btn btn-secondary btn-sm" data-reset="${attr(a.username)}">Reset Password</button></td></tr>`).join('')}</tbody></table></div>`;$('addAdmin').onclick=openAddAdmin;document.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>openResetPassword(b.dataset.reset));}
function openAddAdmin(){openModal('Add Administrator',`<div class="form-grid"><div class="field"><label>Name</label><input id="admName" class="control"></div><div class="field"><label>Username</label><input id="admUser" class="control"></div><div class="field"><label>Password</label><input id="admPass" type="password" class="control"></div></div>`,[{text:'Cancel',cls:'btn-secondary',fn:closeModal},{text:'Create',cls:'btn-primary',fn:async()=>{const name=clean($('admName').value),username=clean($('admUser').value),password=$('admPass').value;if(!name||!username||password.length<8){toast('Name, username, and an 8+ character password are required.','error');return;}const h=await hashPassword(password);await save(db=>{if([...db.admins,...db.users].some(x=>clean(x.username).toLowerCase()===username.toLowerCase()))throw new Error('Username already exists.');db.admins.push({id:uid('ADM'),name,username,role:'Administrator',active:true,passwordHash:h.hash,passwordSalt:h.salt,passwordIterations:h.iterations,mustChangePassword:false,updatedAt:new Date().toISOString(),updatedBy:State.session.username});audit(db,'ADMIN_CREATED',{newValue:username,details:name});},`Create admin ${username}`);closeModal();renderAdmins();}}]);}
function openResetPassword(username){openModal(`Reset ${username}`,`<div class="field"><label>New temporary password</label><input id="resetPassword" type="password" class="control"></div>`,[{text:'Cancel',cls:'btn-secondary',fn:closeModal},{text:'Reset',cls:'btn-primary',fn:async()=>{const p=$('resetPassword').value;if(p.length<8){toast('Password must be at least 8 characters.','error');return;}await adminResetPassword(username,p);await reload();closeModal();toast('Password reset. User must change it after sign-in.');}}]);}

function renderSkills(){roleGuard();const by={};State.db.skills.filter(s=>s.active!==false).forEach(s=>(by[s.username]??=[]).push(s));$('content').innerHTML=`<div class="section-title"><div><h3>Employee Skills</h3><p>Normal scheduling skills are separate from Off-Day Coverage Skills in the pharmacist profile.</p></div></div><div class="card mb12"><div class="form-grid-3"><div class="field"><label>Pharmacist</label><select id="skillUser" class="control">${State.db.users.map(u=>`<option value="${attr(u.username)}">${esc(u.pharmacistName||u.name)}</option>`).join('')}</select></div><div class="field"><label>Skill code</label><input id="skillCode" class="control" placeholder="CC1"></div><div class="field"><label>&nbsp;</label><button id="addSkill" class="btn btn-primary">Add Skill</button></div></div></div><div class="grid-3">${State.db.users.map(u=>`<div class="card"><h3>${esc(u.pharmacistName||u.name)}</h3><div class="chips">${(by[u.username]||[]).map(s=>`<span class="chip">${esc(s.skill)} <button class="btn btn-sm btn-ghost" data-del-skill="${attr(s.id)}">×</button></span>`).join('')||'<span class="muted">No normal skills</span>'}</div><p class="small muted">OFF-day only: ${esc((u.offDayCoverageSkills||[]).join(', ')||'None')}</p></div>`).join('')}</div>`;$('addSkill').onclick=async()=>{const username=$('skillUser').value,skill=clean($('skillCode').value).toUpperCase();if(!skill)return;await save(db=>{const u=db.users.find(x=>x.username===username);if(!db.skills.some(x=>x.username===username&&clean(x.skill).toUpperCase()===skill&&x.active!==false))db.skills.push({id:uid('SKL'),employeeId:u?.id||'',pharmacistName:u?.pharmacistName||u?.name||'',username,skill,active:true,updatedAt:new Date().toISOString(),updatedBy:State.session.username});audit(db,'SKILL_ADDED',{pharmacist:u?.pharmacistName||'',newValue:skill});},`Add skill ${skill}`);renderSkills();};document.querySelectorAll('[data-del-skill]').forEach(b=>b.onclick=async()=>{await save(db=>{const s=db.skills.find(x=>x.id===b.dataset.delSkill);db.skills=db.skills.filter(x=>x.id!==b.dataset.delSkill);audit(db,'SKILL_REMOVED',{pharmacist:s?.pharmacistName||'',oldValue:s?.skill||''});},'Remove skill');renderSkills();});}

function renderShifts(){roleGuard();$('content').innerHTML=`<div class="section-title"><div><h3>Shift Definitions</h3><p>Hours are actual duration; Credited Hours controls scheduling-hour calculations.</p></div><button id="addShift" class="btn btn-primary">+ Add Shift</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Shift</th><th>Meaning</th><th>Start</th><th>End</th><th>Hours</th><th>Credited</th><th>Type</th><th>Skill</th><th>Weekend</th><th>Active</th><th>Priority</th><th></th></tr></thead><tbody>${State.db.shifts.map(s=>`<tr><td><b>${esc(s.shift)}</b></td><td>${esc(s.meaning)}</td><td>${esc(s.start)}</td><td>${esc(s.end)}</td><td>${s.hours}</td><td>${s.creditedHours}</td><td>${esc(s.type)}</td><td>${esc(s.skill)}</td><td>${boolBadge(s.weekend)}</td><td>${boolBadge(s.active)}</td><td>${s.priority}</td><td><button class="btn btn-secondary btn-sm" data-edit-shift="${attr(s.shift)}">Edit</button></td></tr>`).join('')}</tbody></table></div>`;$('addShift').onclick=()=>openShift('');document.querySelectorAll('[data-edit-shift]').forEach(b=>b.onclick=()=>openShift(b.dataset.editShift));}
function openShift(code){const s=code?State.db.shifts.find(x=>x.shift===code):{...SHIFT_DEFAULTS};openModal(code?'Edit Shift':'Add Shift',`<div class="form-grid"><div class="field"><label>Shift Code</label><input id="sh_code" class="control" value="${attr(s.shift||'')}" ${code?'disabled':''}></div><div class="field"><label>Meaning</label><input id="sh_meaning" class="control" value="${attr(s.meaning||'')}"></div><div class="field"><label>Start</label><input id="sh_start" type="time" class="control" value="${attr(s.start||'')}"></div><div class="field"><label>End</label><input id="sh_end" type="time" class="control" value="${attr(s.end||'')}"></div><div class="field"><label>Hours</label><input id="sh_hours" type="number" step="0.25" class="control" value="${attr(s.hours||0)}"></div><div class="field"><label>Credited Hours</label><input id="sh_credited" type="number" step="0.25" class="control" value="${attr(s.creditedHours||0)}"></div><div class="field"><label>Type</label><select id="sh_type" class="control">${['Day','Evening','Night','Training','Other'].map(x=>`<option ${s.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Required Skill</label><input id="sh_skill" class="control" value="${attr(s.skill||'')}"></div><div class="field"><label>Weekend Shift</label><select id="sh_weekend" class="control"><option value="true" ${yes(s.weekend)?'selected':''}>Yes</option><option value="false" ${!yes(s.weekend)?'selected':''}>No</option></select></div><div class="field"><label>Active</label><select id="sh_active" class="control"><option value="true" ${s.active!==false?'selected':''}>Yes</option><option value="false" ${s.active===false?'selected':''}>No</option></select></div><div class="field"><label>Priority</label><input id="sh_priority" type="number" class="control" value="${attr(s.priority||50)}"></div></div>`,[{text:'Cancel',cls:'btn-secondary',fn:closeModal},...(code?[{text:'Delete',cls:'btn-danger',fn:()=>deleteShift(code)}]:[]),{text:'Save',cls:'btn-primary',fn:()=>saveShift(code)}]);}
async function saveShift(oldCode){const code=clean($('sh_code').value).toUpperCase();if(!code){toast('Shift code required.','error');return;}await save(db=>{let s=oldCode?db.shifts.find(x=>x.shift===oldCode):null;if(!s){if(db.shifts.some(x=>x.shift===code))throw new Error('Shift already exists.');s={};db.shifts.push(s);}Object.assign(s,{shift:code,meaning:$('sh_meaning').value,start:$('sh_start').value,end:$('sh_end').value,hours:num($('sh_hours').value),creditedHours:num($('sh_credited').value),type:$('sh_type').value,skill:clean($('sh_skill').value).toUpperCase(),weekend:$('sh_weekend').value==='true',active:$('sh_active').value==='true',priority:num($('sh_priority').value,50),updatedAt:new Date().toISOString(),updatedBy:State.session.username});audit(db,oldCode?'SHIFT_UPDATED':'SHIFT_CREATED',{newShift:code});},`Save shift ${code}`);closeModal();renderShifts();}
async function deleteShift(code){if(!confirm(`Delete shift ${code}?`))return;await save(db=>{db.shifts=db.shifts.filter(x=>x.shift!==code);db.staffingRequirements=db.staffingRequirements.filter(x=>x.shift!==code);audit(db,'SHIFT_DELETED',{oldShift:code});},`Delete shift ${code}`);closeModal();renderShifts();}

function renderStaffing(){roleGuard();const reqBy=Object.fromEntries(State.db.staffingRequirements.map(r=>[r.shift,r]));$('content').innerHTML=`<div class="section-title"><div><h3>Staffing Requirements</h3><p>Required number of pharmacists for each active shift by weekday.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Shift</th>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map(d=>`<th>${d.slice(0,3)}</th>`).join('')}<th>Active</th><th></th></tr></thead><tbody>${State.db.shifts.map(s=>{const r=reqBy[s.shift]||{shift:s.shift,active:true};return `<tr><td><b>${esc(s.shift)}</b></td>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map(d=>`<td><input class="control" style="width:72px" type="number" min="0" data-req="${attr(s.shift)}|${d}" value="${num(r[d],0)}"></td>`).join('')}<td><input type="checkbox" data-req-active="${attr(s.shift)}" ${r.active!==false?'checked':''}></td><td><button class="btn btn-primary btn-sm" data-save-req="${attr(s.shift)}">Save</button></td></tr>`}).join('')}</tbody></table></div>`;document.querySelectorAll('[data-save-req]').forEach(b=>b.onclick=async()=>{const shift=b.dataset.saveReq;await save(db=>{let r=db.staffingRequirements.find(x=>x.shift===shift);if(!r){r={id:uid('REQ'),shift};db.staffingRequirements.push(r);}for(const d of ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'])r[d]=num(document.querySelector(`[data-req="${CSS.escape(shift+'|'+d)}"]`).value,0);r.active=document.querySelector(`[data-req-active="${CSS.escape(shift)}"]`).checked;r.updatedAt=new Date().toISOString();r.updatedBy=State.session.username;audit(db,'STAFFING_UPDATED',{newShift:shift});},`Update staffing ${shift}`);toast(`${shift} staffing saved.`);});}

function renderRequests(){const mine=State.db.requests.filter(r=>State.session.isAdmin||r.username===State.session.username);$('content').innerHTML=`<div class="section-title"><div><h3>PTO / Availability</h3><p>The first ${num(State.db.settings.ptoAutoApprovalLimitPerDate,2)} PTO requests for each requested date are auto-approved first-come.</p></div><div><button id="newPto" class="btn btn-primary">Request PTO</button> <button id="newAvail" class="btn btn-secondary">Add Availability Record</button></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Type</th><th>Pharmacist</th><th>Date / Range</th><th>Available</th><th>Status</th><th>Comment</th><th>Submitted</th>${State.session.isAdmin?'<th>Review</th>':''}</tr></thead><tbody>${mine.sort((a,b)=>String(b.submittedAt).localeCompare(String(a.submittedAt))).map(r=>`<tr><td>${esc(r.recordType)}</td><td>${esc(r.pharmacist)}</td><td>${esc(r.startDate||r.date||'')}${r.endDate&&r.endDate!==(r.startDate||r.date)?' → '+esc(r.endDate):''}</td><td>${r.available==null?'':boolBadge(r.available)}</td><td><span class="badge ${clean(r.status).toLowerCase()==='approved'?'badge-ok':clean(r.status).toLowerCase()==='pending'?'badge-warn':''}">${esc(r.status||'')}</span></td><td>${esc(r.comment||'')}</td><td>${esc(fmt(r.submittedAt))}</td>${State.session.isAdmin?`<td>${clean(r.status).toLowerCase()==='pending'?`<button class="btn btn-success btn-sm" data-review="${attr(r.recordId)}|Approved">Approve</button> <button class="btn btn-danger btn-sm" data-review="${attr(r.recordId)}|Rejected">Reject</button>`:''}</td>`:''}</tr>`).join('')}</tbody></table></div>`;$('newPto').onclick=openPto;$('newAvail').onclick=openAvailabilityRecord;document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const [id,status]=b.dataset.review.split('|');reviewRequest(id,status)});}
function openPto(){openModal('Request PTO',`<div class="form-grid"><div class="field"><label>Start Date</label><input id="ptoStart" type="date" class="control"></div><div class="field"><label>End Date</label><input id="ptoEnd" type="date" class="control"></div></div><div class="field mt12"><label>Comment</label><textarea id="ptoComment" class="control"></textarea></div>`,[{text:'Cancel',cls:'btn-secondary',fn:closeModal},{text:'Submit',cls:'btn-primary',fn:async()=>{const start=$('ptoStart').value,end=$('ptoEnd').value||start;if(!start){toast('Start date required.','error');return;}await save(db=>{const user=db.users.find(x=>x.username===State.session.username)||{pharmacistName:State.session.name};db.requests.push({recordType:'PTO',recordId:uid('PTO'),pharmacist:user.pharmacistName||user.name,username:State.session.username,startDate:start,endDate:end,status:'Pending',comment:$('ptoComment').value,submittedAt:new Date().toISOString(),reviewedBy:'',reviewedAt:'',updatedAt:new Date().toISOString(),updatedBy:State.session.username});reconcilePto(db);audit(db,'PTO_SUBMITTED',{date:start,pharmacist:user.pharmacistName||user.name,newValue:end});},'Submit PTO');closeModal();toast('PTO request submitted.');renderRequests();}}]);}
function openAvailabilityRecord(){openModal('Availability / Unavailable Date',`<div class="form-grid"><div class="field"><label>Date</label><input id="avDate" type="date" class="control"></div><div class="field"><label>Available</label><select id="avAvailable" class="control"><option value="true">Yes</option><option value="false">No</option></select></div></div><div class="field mt12"><label>Comment</label><textarea id="avComment" class="control"></textarea></div>`,[{text:'Cancel',cls:'btn-secondary',fn:closeModal},{text:'Save',cls:'btn-primary',fn:async()=>{const date=$('avDate').value;if(!date)return;await save(db=>{const u=db.users.find(x=>x.username===State.session.username);db.requests.push({recordType:'AVAILABILITY',recordId:uid('AVL'),pharmacist:u?.pharmacistName||State.session.name,username:State.session.username,date,available:$('avAvailable').value==='true',status:'Approved',comment:$('avComment').value,submittedAt:new Date().toISOString(),updatedAt:new Date().toISOString(),updatedBy:State.session.username});audit(db,'AVAILABILITY_SAVED',{date,pharmacist:u?.pharmacistName||State.session.name,newValue:$('avAvailable').value});},'Save availability');closeModal();renderRequests();}}]);}
async function reviewRequest(id,status){await save(db=>{const r=db.requests.find(x=>x.recordId===id);r.status=status;r.reviewedBy=State.session.username;r.reviewedAt=new Date().toISOString();r.updatedAt=new Date().toISOString();r.updatedBy=State.session.username;reconcilePto(db);audit(db,'REQUEST_REVIEWED',{date:r.startDate||r.date,pharmacist:r.pharmacist,newValue:status,details:id});},`Review request ${id}`);renderRequests();}

function renderWeeklyAvailability(){const users=State.session.isAdmin?State.db.users:State.db.users.filter(u=>u.username===State.session.username);const rows=State.db.weeklyAvailability.filter(r=>State.session.isAdmin||r.username===State.session.username);$('content').innerHTML=`<div class="section-title"><div><h3>Weekly Availability</h3><p>Recurring weekday availability and time windows.</p></div><button id="addWeekly" class="btn btn-primary">+ Add Rule</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Pharmacist</th><th>Day</th><th>Available</th><th>Start</th><th>End</th><th>Rule</th><th>Effective</th><th>Notes</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.pharmacistName)}</td><td>${esc(r.day)}</td><td>${boolBadge(r.available)}</td><td>${esc(r.startTime)}</td><td>${esc(r.endTime)}</td><td>${esc(r.ruleType)}</td><td>${esc(r.effectiveStart||'')} ${r.effectiveEnd?'→ '+esc(r.effectiveEnd):''}</td><td>${esc(r.notes||'')}</td><td><button class="btn btn-danger btn-sm" data-del-week="${attr(r.id)}">Delete</button></td></tr>`).join('')}</tbody></table></div>`;$('addWeekly').onclick=()=>{openModal('Add Weekly Availability',`<div class="form-grid"><div class="field"><label>Pharmacist</label><select id="waUser" class="control">${users.map(u=>`<option value="${attr(u.username)}">${esc(u.pharmacistName||u.name)}</option>`).join('')}</select></div><div class="field"><label>Day</label><select id="waDay" class="control">${['SUN','MON','TUE','WED','THU','FRI','SAT'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Available</label><select id="waAvailable" class="control"><option value="true">Yes</option><option value="false">No</option></select></div><div class="field"><label>Rule Type</label><select id="waRule" class="control"><option>AVAILABLE</option><option>BLOCK</option></select></div><div class="field"><label>Start Time</label><input id="waStart" type="time" class="control"></div><div class="field"><label>End Time</label><input id="waEnd" type="time" class="control"></div><div class="field"><label>Effective Start</label><input id="waEffStart" type="date" class="control"></div><div class="field"><label>Effective End</label><input id="waEffEnd" type="date" class="control"></div><div class="field"><label>Notes</label><textarea id="waNotes" class="control"></textarea></div></div>`,[{text:'Cancel',cls:'btn-secondary',fn:closeModal},{text:'Save',cls:'btn-primary',fn:async()=>{const username=$('waUser').value,u=State.db.users.find(x=>x.username===username);await save(db=>{db.weeklyAvailability.push({id:uid('WAV'),employeeId:u?.id||'',pharmacistName:u?.pharmacistName||u?.name||'',username,day:$('waDay').value,available:$('waAvailable').value==='true',startTime:$('waStart').value,endTime:$('waEnd').value,ruleType:$('waRule').value,effectiveStart:$('waEffStart').value,effectiveEnd:$('waEffEnd').value,notes:$('waNotes').value,active:true,updatedAt:new Date().toISOString(),updatedBy:State.session.username});audit(db,'WEEKLY_AVAILABILITY_ADDED',{pharmacist:u?.pharmacistName||'',newValue:$('waDay').value});},'Add weekly availability');closeModal();renderWeeklyAvailability();}}]);};document.querySelectorAll('[data-del-week]').forEach(b=>b.onclick=async()=>{await save(db=>{db.weeklyAvailability=db.weeklyAvailability.filter(x=>x.id!==b.dataset.delWeek);audit(db,'WEEKLY_AVAILABILITY_REMOVED',{oldValue:b.dataset.delWeek});},'Remove weekly availability');renderWeeklyAvailability();});}

function renderPreceptors(){roleGuard();const pre=State.db.users.filter(u=>yes(u.preceptor));$('content').innerHTML=`<div class="section-title"><div><h3>Preceptor Calendar</h3><p>ON = pharmacist works the preferred/home unit. OFF = pharmacist may work E1, E2, or the preferred unit. If not precepting the whole month, the evening target is ${num(State.db.settings.preceptorEveningTargetPerMonthWhenOff,7)} per month.</p></div><button id="addPrec" class="btn btn-primary">+ Add Day</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Pharmacist</th><th>Date</th><th>Status</th><th>Rotation</th><th>Notes</th><th></th></tr></thead><tbody>${State.db.preceptorCalendar.sort((a,b)=>a.date.localeCompare(b.date)).map(r=>`<tr><td>${esc(r.pharmacistName)}</td><td>${esc(r.date)}</td><td><span class="badge ${yes(r.precepting)?'badge-ok':''}">${yes(r.precepting)?'ON':'OFF'}</span></td><td>${esc(r.rotation||'')}</td><td>${esc(r.notes||'')}</td><td><button class="btn btn-danger btn-sm" data-del-prec="${attr(r.id)}">Delete</button></td></tr>`).join('')}</tbody></table></div>`;$('addPrec').onclick=()=>openModal('Add Preceptor Calendar Day',`<div class="form-grid"><div class="field"><label>Preceptor</label><select id="pcUser" class="control">${pre.map(u=>`<option value="${attr(u.username)}">${esc(u.pharmacistName||u.name)}</option>`).join('')}</select></div><div class="field"><label>Date</label><input id="pcDate" type="date" class="control"></div><div class="field"><label>Status</label><select id="pcOn" class="control"><option value="true">ON — Precepting</option><option value="false">OFF — Not precepting</option></select></div><div class="field"><label>Rotation</label><input id="pcRotation" class="control"></div><div class="field"><label>Notes</label><textarea id="pcNotes" class="control"></textarea></div></div>`,[{text:'Cancel',cls:'btn-secondary',fn:closeModal},{text:'Save',cls:'btn-primary',fn:async()=>{const username=$('pcUser').value,u=State.db.users.find(x=>x.username===username),date=$('pcDate').value;if(!date)return;await save(db=>{const existing=db.preceptorCalendar.find(x=>x.username===username&&x.date===date);const rec=existing||{id:uid('PRE')};Object.assign(rec,{username,pharmacistName:u?.pharmacistName||u?.name,date,precepting:$('pcOn').value==='true',status:$('pcOn').value==='true'?'ON':'OFF',rotation:$('pcRotation').value,notes:$('pcNotes').value,updatedAt:new Date().toISOString(),updatedBy:State.session.username});if(!existing)db.preceptorCalendar.push(rec);audit(db,'PRECEPTOR_CALENDAR_UPDATED',{date,pharmacist:rec.pharmacistName,newValue:rec.status});},'Save preceptor calendar');closeModal();renderPreceptors();}}]);document.querySelectorAll('[data-del-prec]').forEach(b=>b.onclick=async()=>{await save(db=>{db.preceptorCalendar=db.preceptorCalendar.filter(x=>x.id!==b.dataset.delPrec);audit(db,'PRECEPTOR_CALENDAR_REMOVED',{oldValue:b.dataset.delPrec});},'Remove preceptor day');renderPreceptors();});}

function renderSwaps(){const now=new Date().toISOString().slice(0,10);State.db.swaps.forEach(s=>{if(s.status==='OPEN'&&s.expiresAt&&s.expiresAt<now)s.status='EXPIRED'});const mineAssignments=State.db.schedule.filter(r=>r.username===State.session.username&&r.date>=now&&clean(r.status)!=='UNFILLED');$('content').innerHTML=`<div class="section-title"><div><h3>Swap Market</h3><p>Post a shift, make counter-offers, and accept directly. Offers expire after the posted shift date; no manager authorization is required.</p></div><button id="postSwap" class="btn btn-primary">Post My Shift</button></div><div class="grid-2">${State.db.swaps.sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).map(s=>{const r=State.db.schedule.find(x=>x.assignmentId===s.assignmentId);return `<div class="card"><div class="section-title"><div><h3>${esc(s.postedByName)}</h3><p>${esc(r?.date||s.date)} — ${esc(r?.shift||s.shift)}</p></div><span class="badge ${s.status==='OPEN'?'badge-ok':''}">${esc(s.status)}</span></div><p>${esc(s.note||'')}</p><p class="small muted">Expires ${esc(s.expiresAt||'')}</p><div class="table-wrap"><table class="table"><thead><tr><th>From</th><th>Counter shift</th><th>Status</th><th></th></tr></thead><tbody>${(s.counterOffers||[]).map(o=>{const c=State.db.schedule.find(x=>x.assignmentId===o.assignmentId);return `<tr><td>${esc(o.fromName)}</td><td>${esc(c?.date||'')} ${esc(c?.shift||'')}</td><td>${esc(o.status)}</td><td>${s.postedBy===State.session.username&&s.status==='OPEN'&&o.status==='OPEN'?`<button class="btn btn-success btn-sm" data-accept-swap="${attr(s.swapId)}|${attr(o.offerId)}">Accept</button>`:''}</td></tr>`}).join('')}</tbody></table></div>${s.status==='OPEN'&&s.postedBy!==State.session.username?`<button class="btn btn-secondary mt12" data-counter="${attr(s.swapId)}">Counter-Offer</button>`:''}</div>`}).join('')||'<div class="card muted">No swap postings.</div>'}</div>`;$('postSwap').onclick=()=>openModal('Post Shift',`<div class="field"><label>Your future shift</label><select id="swapAssignment" class="control">${mineAssignments.map(r=>`<option value="${attr(r.assignmentId)}">${esc(r.date)} — ${esc(r.shift)}</option>`).join('')}</select></div><div class="field mt12"><label>Note</label><textarea id="swapNote" class="control"></textarea></div>`,[{text:'Cancel',cls:'btn-secondary',fn:closeModal},{text:'Post',cls:'btn-primary',fn:async()=>{const id=$('swapAssignment').value,r=State.db.schedule.find(x=>x.assignmentId===id);if(!r){toast('No shift selected.','error');return;}await save(db=>{if(db.swaps.some(s=>s.assignmentId===id&&s.status==='OPEN'))throw new Error('This shift is already posted.');db.swaps.push({swapId:uid('SWP'),postedBy:State.session.username,postedByName:State.session.name,assignmentId:id,date:r.date,shift:r.shift,note:$('swapNote').value,status:'OPEN',createdAt:new Date().toISOString(),expiresAt:r.date,counterOffers:[]});audit(db,'SWAP_POSTED',{date:r.date,pharmacist:State.session.name,newShift:r.shift});},'Post shift swap');closeModal();renderSwaps();}}]);document.querySelectorAll('[data-counter]').forEach(b=>b.onclick=()=>openCounter(b.dataset.counter));document.querySelectorAll('[data-accept-swap]').forEach(b=>b.onclick=()=>{const [s,o]=b.dataset.acceptSwap.split('|');acceptSwap(s,o)});}
function openCounter(swapId){const s=State.db.swaps.find(x=>x.swapId===swapId);const eligible=swapEligibleCounterShifts(State.db,s.postedBy,State.session.username,s.assignmentId);openModal('Counter-Offer',eligible.length?`<div class="field"><label>Your available shift to offer</label><select id="counterAssignment" class="control">${eligible.map(r=>`<option value="${attr(r.assignmentId)}">${esc(r.date)} — ${esc(r.shift)}</option>`).join('')}</select></div>`:`<div class="alert alert-warn">You have no eligible future shifts to counter-offer. Shifts on dates where the other pharmacist already works are excluded.</div>`,[{text:'Cancel',cls:'btn-secondary',fn:closeModal},...(eligible.length?[{text:'Send Offer',cls:'btn-primary',fn:async()=>{const aid=$('counterAssignment').value;await save(db=>{const x=db.swaps.find(y=>y.swapId===swapId);x.counterOffers=x.counterOffers||[];x.counterOffers.push({offerId:uid('OFR'),from:State.session.username,fromName:State.session.name,assignmentId:aid,status:'OPEN',createdAt:new Date().toISOString()});audit(db,'SWAP_COUNTER_OFFERED',{pharmacist:State.session.name,newValue:swapId});},'Counter offer');closeModal();renderSwaps();}}]:[])]);}
async function acceptSwap(swapId,offerId){const s=State.db.swaps.find(x=>x.swapId===swapId),o=s?.counterOffers?.find(x=>x.offerId===offerId);if(!s||!o)return;const a=State.db.schedule.find(x=>x.assignmentId===s.assignmentId),b=State.db.schedule.find(x=>x.assignmentId===o.assignmentId);if(!a||!b){toast('One of the shifts no longer exists.','error');return;}const wa=manualAssignmentWarnings(State.db,a.assignmentId,b.username),wb=manualAssignmentWarnings(State.db,b.assignmentId,a.username);if(!wa.ok||!wb.ok){toast(`Swap cannot be accepted because it violates scheduling rules: ${[...wa.reasons,...wb.reasons].join(', ')}`,'error');return;}if(!confirm(`Swap ${a.date} ${a.shift} with ${b.date} ${b.shift}?`))return;await save(db=>{const sw=db.swaps.find(x=>x.swapId===swapId),of=sw.counterOffers.find(x=>x.offerId===offerId),ra=db.schedule.find(x=>x.assignmentId===sw.assignmentId),rb=db.schedule.find(x=>x.assignmentId===of.assignmentId);const ua=db.users.find(x=>x.username===ra.username),ub=db.users.find(x=>x.username===rb.username);const temp={username:ra.username,name:ra.assignedPharmacist};ra.username=rb.username;ra.assignedPharmacist=rb.assignedPharmacist;rb.username=temp.username;rb.assignedPharmacist=temp.name;ra.manual=rb.manual=true;ra.status=rb.status='SWAPPED';ra.updatedAt=rb.updatedAt=new Date().toISOString();ra.updatedBy=rb.updatedBy=State.session.username;sw.status='ACCEPTED';of.status='ACCEPTED';sw.counterOffers.filter(x=>x.offerId!==offerId&&x.status==='OPEN').forEach(x=>x.status='DECLINED');audit(db,'SWAP_ACCEPTED',{date:ra.date,pharmacist:ua?.pharmacistName||temp.name,oldShift:ra.shift,newShift:rb.shift,details:`${swapId}; with ${ub?.pharmacistName||rb.assignedPharmacist}`});},`Accept swap ${swapId}`);toast('Swap completed.');renderSwaps();}

function renderSettings(){roleGuard();const s=State.db.settings;const fields=[['scheduleDays','Default Schedule Days','number'],['weeklyHoursLimit','Weekly Hours Limit','number'],['requiredHoursPerSchedulePeriod','Required Hours Per Schedule Period','number'],['maximumHoursPerSchedulePeriod','Maximum Hours Per Schedule Period','number'],['regularWorkdaysPerWeek','Regular Workdays Per Week','number'],['maximumConsecutiveWorkdays','Maximum Consecutive Workdays','number'],['maximumEveningShifts','Maximum Evening Shifts','number'],['weekStart','Week Start','text'],['weekendAnchorDate','Weekend Anchor Date','date'],['weekendAnchorGroup','Weekend Anchor Group','text'],['residentE2ShiftCode','Resident E2 Shift Code','text'],['residentE2ShiftsPerWeek','Resident E2 Shifts Per Week','number'],['edDayShiftCode','ED Day Shift Code','text'],['edEveningShiftCode','ED Evening Shift Code','text'],['ptoAutoApprovalLimitPerDate','PTO Auto-Approval Limit Per Date','number'],['preceptorEveningTargetPerMonthWhenOff','Preceptor Evening Target Per Month When OFF','number'],['minimumRestHours','Minimum Rest Hours','number']];$('content').innerHTML=`<div class="section-title"><div><h3>Settings</h3><p>These values drive the scheduler; they are not hard-coded in the algorithm.</p></div><button id="saveSettings" class="btn btn-primary">Save Settings</button></div><div class="form-grid">${fields.map(([k,l,t])=>`<div class="field"><label>${esc(l)}</label><input id="set_${k}" class="control" type="${t}" value="${attr(s[k]??'')}"></div>`).join('')}<div class="field"><label>Weekend Rotation</label><input id="set_weekendRotation" class="control" value="${attr((s.weekendRotation||['A','B','C']).join(', '))}"></div>${[['allowWeekendFallback','Allow Weekend Fallback'],['requiredWeekendAssignment','Required Weekend Assignment'],['residentsRequiredAssignedWeekend','Residents Required Assigned Weekend'],['sevenOnBlockScheduling','Seven-On Block Scheduling'],['blockEveningToMorningTransition','Block Evening → Morning'],['allowAdminRuleOverride','Allow Admin Rule Override'],['showFullScheduleToPharmacists','Show Full Schedule To Pharmacists'],['preceptorHomeUnitRequiredWhenOn','Preceptor Home Unit Required When ON'],['preceptorOffAllowsEvenings','Preceptor OFF Allows E1/E2'],['eddEdePairRequired','EDD/EDE Pair Required']].map(([k,l])=>`<div class="field"><label>${esc(l)}</label><select id="set_${k}" class="control"><option value="true" ${yes(s[k])?'selected':''}>Yes</option><option value="false" ${!yes(s[k])?'selected':''}>No</option></select></div>`).join('')}</div>`;$('saveSettings').onclick=async()=>{await save(db=>{for(const [k,,t] of fields)db.settings[k]=t==='number'?num($(`set_${k}`).value):$(`set_${k}`).value;db.settings.weekendRotation=$('set_weekendRotation').value.split(',').map(x=>clean(x).toUpperCase()).filter(Boolean);for(const [k] of [['allowWeekendFallback'],['requiredWeekendAssignment'],['residentsRequiredAssignedWeekend'],['sevenOnBlockScheduling'],['blockEveningToMorningTransition'],['allowAdminRuleOverride'],['showFullScheduleToPharmacists'],['preceptorHomeUnitRequiredWhenOn'],['preceptorOffAllowsEvenings'],['eddEdePairRequired']])db.settings[k]=$(`set_${k}`).value==='true';audit(db,'SETTINGS_UPDATED',{details:'Scheduler settings changed.'});},'Update settings');toast('Settings saved.');renderSettings();};}

function renderFairness(){roleGuard();const f=fairnessReport(State.db);$('content').innerHTML=`<div class="section-title"><div><h3>Fairness Report</h3><p>Average scheduled hours: ${f.averageHours}</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Pharmacist</th><th>Total Hours</th><th>vs Avg</th><th>Shifts</th><th>Day</th><th>Evening</th><th>Night</th><th>Weekend</th><th>Flag</th></tr></thead><tbody>${f.employees.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.totalHours}</td><td>${x.hoursVsAverage}</td><td>${x.shifts}</td><td>${x.dayShifts}</td><td>${x.eveningShifts}</td><td>${x.nightShifts}</td><td>${x.weekendShifts}</td><td><span class="badge ${x.workloadFlag==='HIGH'?'badge-warn':x.workloadFlag==='LOW'?'badge-danger':'badge-ok'}">${x.workloadFlag}</span></td></tr>`).join('')}</tbody></table></div>`;}
function renderAudit(){roleGuard();$('content').innerHTML=`<div class="section-title"><div><h3>Audit Log</h3><p>Important schedule, credential, PTO, skills, and configuration changes.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Timestamp</th><th>User</th><th>Action</th><th>Date</th><th>Pharmacist</th><th>Old</th><th>New</th><th>Override</th><th>Details</th></tr></thead><tbody>${[...State.db.audit].sort((a,b)=>String(b.timestamp).localeCompare(String(a.timestamp))).slice(0,1000).map(a=>`<tr><td>${esc(fmt(a.timestamp))}</td><td>${esc(a.user)}</td><td>${esc(a.action)}</td><td>${esc(a.date||'')}</td><td>${esc(a.pharmacist||'')}</td><td>${esc(a.oldValue||a.oldShift||'')}</td><td>${esc(a.newValue||a.newShift||'')}</td><td>${yes(a.override)?`<span class="badge badge-warn">Yes</span> ${esc(a.overrideReason||'')}`:''}</td><td>${esc(a.details||'')}</td></tr>`).join('')}</tbody></table></div>`;}

function openChangePassword(){openModal('Change Password',`<div class="field"><label>Current password</label><input id="cpCurrent" type="password" class="control"></div><div class="field mt12"><label>New password</label><input id="cpNew" type="password" class="control"></div><div class="field mt12"><label>Confirm new password</label><input id="cpConfirm" type="password" class="control"></div>`,[{text:'Cancel',cls:'btn-secondary',fn:closeModal},{text:'Change Password',cls:'btn-primary',fn:async()=>{const n=$('cpNew').value;if(n!==$('cpConfirm').value){toast('Passwords do not match.','error');return;}try{await changePassword($('cpCurrent').value,n);closeModal();toast('Password changed.');}catch(e){toast(e.message,'error');}}}]);}

function openModal(title,body,actions=[]){$('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h3>${esc(title)}</h3><button id="modalX" class="btn btn-ghost">×</button></div><div class="modal-body">${body}</div><div class="modal-actions" id="modalActions"></div></div></div>`;$('modalX').onclick=closeModal;for(const a of actions){const b=document.createElement('button');b.className=`btn ${a.cls||'btn-secondary'}`;b.textContent=a.text;b.onclick=a.fn;$('modalActions').appendChild(b);}}
function closeModal(){$('modalRoot').innerHTML='';}

boot();
